#[test]
fn test_tall_digit() {

    let grid = TileGrid::<DigitTile, 7, 4>::fill(DigitTile::Empty)
        .builder(1, 1).write_multi::<TallDigit>("16384").build();
    let composed = grid.compose_image(&DIGIT_ATLAS, 11);
    assert_eq!(composed, DIGIT_COMPOSED.to_vec());

}